			}
			// Pad leftPart to leftWidth
			// Calculate display width (approx)
			// For simplicity, use len
			paddedLeft := leftPart
			// Need to handle ANSI codes not counted in length - skip for now
			visibleLen := len(leftPart) // approximate
			// Remove ANSI for length calc? We'll just pad based on rune count without escape
			// Strip ANSI for length
			plainLeft := stripAnsi(leftPart)
