		}
		colWidth := maxLen + 4
		if colWidth < 15 {
			colWidth = 15
		}
		cols := width / colWidth
		if cols < 1 {
			cols = 1
		}
		// For rendering, list files in columns (like ls)
		// We'll render row by row
		rows := (len(st.files) + cols - 1) / cols

		// Adjust for height
		// If many files, paginate? For simplicity, show first height-2 rows * cols files?

		for r := 0; r < rows; r++ {
			if r >= height-2 {
				break
			}
			for c := 0; c < cols; c++ {
				idx := c*rows + r
				if idx >= len(st.files) {
