	}

	fmt.Fprint(os.Stderr, buf.String())
}

func stripAnsi(s string) string {
	// Remove ANSI escape sequences like \x1b[...m and \x1b[?.. etc
	var out strings.Builder
	inEsc := false
	for i := 0; i < len(s); {
		if !inEsc && s[i] == 0x1b {
			// start escape
			inEsc = true
			i++
			continue
		}
		if inEsc {
			// escape ends with letter
			if (s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= 'a' && s[i] <= 'z') {
				inEsc = false
			}
			i++
			continue
		}
		out.WriteByte(s[i])
		i++
	}
	return out.String()
}
