func splitCommaRespectParen(s string) []string {
	var res []string
	var cur bytes.Buffer
	depth := 0
	inQuote := false
	var quoteChar rune
	for _, r := range s {
		if inQuote {
			if r == quoteChar {
				inQuote = false
			}
			cur.WriteRune(r)
			continue
		}
		if r == '"' || r == '\'' {
			inQuote = true
			quoteChar = r
			cur.WriteRune(r)
			continue
		}
		if r == '(' {
			depth++
			cur.WriteRune(r)
			continue
		}
		if r == ')' {
			depth--
			cur.WriteRune(r)
			continue
		}
		if r == ',' && depth == 0 {
			res = append(res, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if cur.Len() > 0 {
		res = append(res, cur.String())
	}
	return res
