			}
			cur.WriteRune(r)
			continue
		}
		if r == '"' || r == '\'' {
			inQuote = true
			quoteChar = r
			cur.WriteRune(r)
			continue
		}
		if r == '(' {
			depth++
			cur.WriteRune(r)
			continue
		}
		if r == ')' {
			depth--
			cur.WriteRune(r)
			continue
		}
		if r == ',' && depth == 0 {
			res = append(res, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteRune(r)
	}
	if cur.Len() > 0 {
		res = append(res, cur.String())
	}
	return res
}

