func enableRaw(fd int) (*syscall.Termios, error) {
	var old syscall.Termios
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&old)), 0, 0, 0)
	if err != 0 {
		return nil, err
	}
	new := old
	new.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG
	new.Iflag &^= syscall.IXON | syscall.ICRNL
	new.Cc[syscall.VMIN] = 1
	new.Cc[syscall.VTIME] = 0
	_, _, err = syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&new)), 0, 0, 0)
	if err != 0 {
		return nil, err
	}
	return &old, nil
}

func disableRaw(fd int, old *syscall.Termios) {
	syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(old)), 0, 0, 0)
}

