func readFiles(currentPath string, hideHidden, dirOnly bool, fuzzyQuery string, fuzzy bool) ([]fileEntry, string) {
	fi, err := os.Stat(currentPath)
	if err != nil {
		return nil, fmt.Sprintf("open %s: no such file or directory", currentPath)
	}
	if !fi.IsDir() {
		return nil, fmt.Sprintf("readdirent %s: not a directory", currentPath)
	}
	entries, err := os.ReadDir(currentPath)
	if err != nil {
		return nil, fmt.Sprintf("open %s: %v", currentPath, err)
	}
	var files []fileEntry
	for _, e := range entries {
		name := e.Name()
		if hideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if dirOnly {
			if !e.IsDir() {
				path := filepath.Join(currentPath, name)
				sfi, err := os.Stat(path)
				if err != nil || !sfi.IsDir() {
					continue
				}
			}
		}
		if fuzzy && fuzzyQuery != "" {
			// case-insensitive substring fuzzy
			if !strings.Contains(strings.ToLower(name), strings.ToLower(fuzzyQuery)) {
				continue
			}
		}
		path := filepath.Join(currentPath, name)
		info, _ := e.Info()
		files = append(files, fileEntry{Name: name, Entry: e, Info: info, Path: path})
	}
	sort.Slice(files, func(i, j int) bool {
		return files[i].Name < files[j].Name
	})
	return files, ""
