		case "--help", "-h":
			helpFlag = true
		case "--version", "-v":
			versionFlag = true
		default:
			if pathArg == "" {
				pathArg = a
			}
		}
	}

	if versionFlag {
		fmt.Fprintln(os.Stdout, version)
		os.Exit(0)
	}
	if helpFlag {
		fmt.Fprint(os.Stderr, helpText)
		os.Exit(1)
	}

	cwd, err := os.Getwd()
	if err != nil {
		cwd = "."
	}
	initPath := ""
	if pathArg != "" {
		if filepath.IsAbs(pathArg) {
			initPath = pathArg
		} else {
			initPath = filepath.Join(cwd, pathArg)
		}
		// Clean
		initPath = filepath.Clean(initPath)
	} else {
		initPath = cwd
	}

	ttyFile, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintln(os.Stderr, "panic: could not open a new TTY: open /dev/tty: no such device or address")
		fmt.Fprintln(os.Stderr, "")
		fmt.Fprintln(os.Stderr, "goroutine 1 [running]:")
		fmt.Fprintln(os.Stderr, "main.main()")
		fmt.Fprintln(os.Stderr, "\t/workspace/main.go:135 +0x87d")
		os.Exit(2)
	}
	defer ttyFile.Close()

	termWidth, termHeight := 80, 24
	if w, h := getWinSize(int(ttyFile.Fd())); w > 0 && h > 0 {
		termWidth = w
		termHeight = h
	}

	oldTermios, err := enableRaw(int(ttyFile.Fd()))
	if err != nil {
		fmt.Fprintln(os.Stderr, "failed to enable raw mode")
		os.Exit(2)
	}
	defer disableRaw(int(ttyFile.Fd()), oldTermios)

	fmt.Fprint(os.Stderr, "\x1b[?25l")
	defer fmt.Fprint(os.Stderr, "\x1b[?25h")

	st := state{
		currentPath: initPath,
		preview:     previewFlag,
		withBorder:  withBorder,
		fuzzy:       fuzzyFlag,
		hideHidden:  hideHiddenFlag,
		dirOnly:     dirOnly,
		showIcons:   showIcons,
	}

	files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
	st.files = files
	st.errorMsg = errMsg
	if len(st.files) > 0 {
		st.cursor = 0
	}

	statusBarExpr := os.Getenv("WALK_STATUS_BAR")
	// mainColor ignored for simplicity but could be used

	inputBuf := make([]byte, 64)

	for {
		render(termWidth, termHeight, &st, statusBarExpr)

		n, err := ttyFile.Read(inputBuf)
		if err != nil {
			if err == io.EOF {
				break
			}
			continue
		}
		if n == 0 {
			continue
		}
		data := inputBuf[:n]

		if len(data) == 1 && data[0] == 3 {
			st.quitNoCd = true
			break
		}
		if data[0] == 27 {
			if n == 1 {
				st.quit = true
				break
			}
			if n >= 3 && data[1] == '[' {
				// Check for shift ( ;2 )
				if bytes.Contains(data[:n], []byte(";2")) {
					last := data[n-1]
					if last == 'A' {
						st.cursor = 0
					} else if last == 'B' {
						if len(st.files) > 0 {
							st.cursor = len(st.files) - 1
						}
					} else if last == 'C' {
						if len(st.files) > 0 {
							st.cursor = len(st.files) - 1
						}
					} else if last == 'D' {
						st.cursor = 0
					}
					continue
				}
				switch data[2] {
				case 'A':
					moveCursor(&st, -1, termWidth, termHeight)
				case 'B':
					moveCursor(&st, 1, termWidth, termHeight)
				case 'C':
					moveCursor(&st, 1, termWidth, termHeight, true)
				case 'D':
					moveCursor(&st, -1, termWidth, termHeight, true)
				case '3':
					if n >= 4 && data[3] == '~' {
						handleDelete(&st)
					}
				case 'H':
					st.cursor = 0
				case 'F':
					if len(st.files) > 0 {
						st.cursor = len(st.files) - 1
					}
				}
				// Also handle 1;2...
				continue
			}
		}

		if len(data) == 1 {
			ch := data[0]
			switch ch {
			case 'q':
				if st.showHelp {
					st.showHelp = false
				} else {
					if st.fuzzy {
						st.fuzzyQuery += string(ch)
						files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
						st.files = files
						st.errorMsg = errMsg
						if st.cursor >= len(st.files) {
							st.cursor = len(st.files) - 1
						}
						if st.cursor < 0 {
							st.cursor = 0
						}
					} else {
						st.quit = true
					}
				}
				if st.quit {
					break
				}
			case 'k':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					moveCursor(&st, -1, termWidth, termHeight)
				}
			case 'j':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					moveCursor(&st, 1, termWidth, termHeight)
				}
			case 'h':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					moveCursor(&st, -1, termWidth, termHeight, true)
				}
			case 'l':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					moveCursor(&st, 1, termWidth, termHeight, true)
				}
			case 'g':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					st.cursor = 0
				}
			case 'G':
				if st.fuzzy {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
				} else {
					if len(st.files) > 0 {
						st.cursor = len(st.files) - 1
					}
				}
			case ' ':
				st.preview = !st.preview
			case '.':
				st.hideHidden = !st.hideHidden
				files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
				st.files = files
				st.errorMsg = errMsg
				if st.cursor >= len(st.files) {
					st.cursor = len(st.files) - 1
				}
				if st.cursor < 0 {
					st.cursor = 0
				}
			case '/':
				st.fuzzy = true
				st.fuzzyQuery = ""
				files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
				st.files = files
				st.errorMsg = errMsg
			case 'y':
				if len(st.files) > 0 && st.cursor >= 0 && st.cursor < len(st.files) {
					selected := st.files[st.cursor]
					st.copiedMsg = selected.Path
					st.copiedTime = time.Now()
					b64 := base64.StdEncoding.EncodeToString([]byte(selected.Path))
					seq := fmt.Sprintf("\x1b]52;c;%s\x07", b64)
					fmt.Fprint(os.Stderr, seq)
				}
			case 'd':
				handleDelete(&st)
			case '?':
				st.showHelp = !st.showHelp
			case 'u':
				handleUndo(&st)
			case 127, 8:
				if st.fuzzy && st.fuzzyQuery != "" {
					if len(st.fuzzyQuery) > 0 {
						_, size := utf8.DecodeLastRuneInString(st.fuzzyQuery)
						st.fuzzyQuery = st.fuzzyQuery[:len(st.fuzzyQuery)-size]
						files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
						st.files = files
						st.errorMsg = errMsg
						if st.cursor >= len(st.files) {
							st.cursor = len(st.files) - 1
						}
						if st.cursor < 0 {
							st.cursor = 0
						}
					}
					if st.fuzzyQuery == "" {
						st.fuzzy = false
					}
				} else {
					parent := filepath.Dir(st.currentPath)
					if parent != st.currentPath {
						st.currentPath = parent
						files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
						st.files = files
						st.errorMsg = errMsg
						st.cursor = 0
					}
				}
			case 13, 10:
				if st.showHelp {
					st.showHelp = false
					continue
				}
				if st.fuzzy {
					st.fuzzy = false
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, "", false)
					// keep query filtering? Actually after enter, original keeps filtering? In our earlier test with fuzzy Enter, it opened file content (pager). So we should keep current filtered files? But we clear fuzzy flag to show all? Let's clear query as well to show all on next render? For simplicity, clear fuzzy query but keep selection.
					// Actually we should not reload all files if we want to open selected file; we already have selection.
					// So we set fuzzy false and fuzzyQuery empty, but reload after open? For now reload all.
					st.fuzzyQuery = ""
					st.files = files
					st.errorMsg = errMsg
				}
				if len(st.files) == 0 {
					continue
				}
				if st.cursor < 0 || st.cursor >= len(st.files) {
					continue
				}
				selected := st.files[st.cursor]
				isDir := selected.Entry.IsDir()
				if !isDir {
					fi, err := os.Stat(selected.Path)
					if err == nil && fi.IsDir() {
						isDir = true
					}
				}
				if isDir {
					st.currentPath = selected.Path
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
					st.cursor = 0
				} else {
					openFile(selected.Path)
				}
			default:
				if st.fuzzy && ch >= 32 && ch <= 126 {
					st.fuzzyQuery += string(ch)
					files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
					st.files = files
					st.errorMsg = errMsg
					if st.cursor >= len(st.files) {
						st.cursor = len(st.files) - 1
					}
					if st.cursor < 0 {
						st.cursor = 0
					}
				}
			}
		} else {
			if st.fuzzy {
				str := string(data)
				st.fuzzyQuery += str
				files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
				st.files = files
				st.errorMsg = errMsg
			}
		}

		if st.quit || st.quitNoCd {
			break
		}
	}

	fmt.Fprint(os.Stderr, "\x1b[?25h")
	fmt.Fprint(os.Stderr, "\x1b[2J\x1b[H")

	if st.quitNoCd {
		os.Exit(2)
	}
	fmt.Fprintln(os.Stdout, st.currentPath)
	os.Exit(0)
}

func moveCursor(st *state, delta int, termWidth, termHeight int, horizontal ...bool) {
	if len(st.files) == 0 {
		return
	}
	isHorizontal := false
	if len(horizontal) > 0 && horizontal[0] {
		isHorizontal = true
	}
	if st.preview {
		// preview mode: single column
		newPos := st.cursor + delta
		if newPos < 0 {
			newPos = 0
		}
		if newPos >= len(st.files) {
			newPos = len(st.files) - 1
		}
		st.cursor = newPos
		return
	}
	// non-preview: multi-column grid, column-major
	// compute cols
	maxLen := 0
	for _, f := range st.files {
		l := len(f.Name)
		if f.Entry.IsDir() {
			l++
		}
		if st.showIcons {
			l += 2
		}
		if l > maxLen {
			maxLen = l
		}
	}
	if maxLen == 0 {
		maxLen = 10
	}
	colWidth := maxLen + 4
	if colWidth < 15 {
		colWidth = 15
	}
	cols := termWidth / colWidth
	if cols < 1 {
		cols = 1
	}
	rows := (len(st.files) + cols - 1) / cols
	if rows < 1 {
		rows = 1
	}

	if isHorizontal {
		// left/right moves by rows
		newPos := st.cursor + delta*rows
		if newPos < 0 {
			newPos = 0
		}
		if newPos >= len(st.files) {
			newPos = len(st.files) - 1
		}
		st.cursor = newPos
	} else {
		newPos := st.cursor + delta
		if newPos < 0 {
			newPos = 0
		}
		if newPos >= len(st.files) {
			newPos = len(st.files) - 1
		}
		st.cursor = newPos
	}
}

func handleDelete(st *state) {
	if len(st.files) == 0 {
		return
	}
	if st.cursor < 0 || st.cursor >= len(st.files) {
		return
	}
	selected := st.files[st.cursor]
	removeCmd := os.Getenv("WALK_REMOVE_CMD")
	var err error
	if removeCmd != "" {
		cmdStr := fmt.Sprintf("%s %q", removeCmd, selected.Path)
		cmd := exec.Command("sh", "-c", cmdStr)
		err = cmd.Run()
	} else {
		// move to trash for undo
		trashDir := "/tmp/.walk_trash"
		os.MkdirAll(trashDir, 0755)
		trashPath := filepath.Join(trashDir, fmt.Sprintf("%d_%s", time.Now().UnixNano(), selected.Name))
		err = os.Rename(selected.Path, trashPath)
		if err == nil {
			st.undoStack = append(st.undoStack, undoItem{OrigPath: selected.Path, TrashPath: trashPath})
		} else {
			// fallback to RemoveAll
			err = os.RemoveAll(selected.Path)
		}
	}
	if err != nil {
		return
	}
	files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
	st.files = files
	st.errorMsg = errMsg
	if st.cursor >= len(st.files) {
		st.cursor = len(st.files) - 1
	}
	if st.cursor < 0 {
		st.cursor = 0
	}
}

func handleUndo(st *state) {
	if len(st.undoStack) == 0 {
		return
	}
	last := st.undoStack[len(st.undoStack)-1]
	st.undoStack = st.undoStack[:len(st.undoStack)-1]
	os.Rename(last.TrashPath, last.OrigPath)
	files, errMsg := readFiles(st.currentPath, st.hideHidden, st.dirOnly, st.fuzzyQuery, st.fuzzy)
	st.files = files
	st.errorMsg = errMsg
}

func openFile(path string) {
	openWith := os.Getenv("WALK_OPEN_WITH")
	ext := strings.TrimPrefix(filepath.Ext(path), ".")
	if openWith != "" && ext != "" {
		separators := []string{";", ","}
		mappings := []string{openWith}
		for _, sep := range separators {
			var newMaps []string
			for _, m := range mappings {
				parts := strings.Split(m, sep)
				newMaps = append(newMaps, parts...)
			}
			mappings = newMaps
		}
		for _, mapping := range mappings {
			mapping = strings.TrimSpace(mapping)
			if mapping == "" {
				continue
			}
			idx := strings.Index(mapping, ":")
			if idx == -1 {
				continue
			}
			e := strings.TrimSpace(mapping[:idx])
			cmdStr := strings.TrimSpace(mapping[idx+1:])
			if strings.EqualFold(e, ext) {
				runEditor(cmdStr, path)
				return
			}
		}
	}
	editor := os.Getenv("WALK_EDITOR")
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor != "" {
		runEditor(editor, path)
		return
	}
	builtinPager(path)
}

func runEditor(cmdStr, path string) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()

	shCmd := fmt.Sprintf("%s %q", cmdStr, path)
	cmd := exec.Command("sh", "-c", shCmd)
	cmd.Stdin = tty
	cmd.Stdout = tty
	cmd.Stderr = tty
	cmd.Run()
}

func builtinPager(path string) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()

	data, err := os.ReadFile(path)
	if err != nil {
		return
	}
	isBinary := bytes.Contains(data, []byte{0})
	var lines []string
	if isBinary {
		lines = []string{"binary"}
	} else {
		content := string(data)
		lines = strings.Split(content, "\n")
	}

	w, h := getWinSize(int(tty.Fd()))
	if w == 0 {
		w = 80
	}
	if h == 0 {
		h = 24
	}
	offset := 0
	for {
		fmt.Fprint(tty, "\x1b[2J\x1b[H")
		for i := 0; i < h-1; i++ {
			idx := offset + i
			if idx >= len(lines) {
				break
			}
			line := lines[idx]
			if len(line) > w {
				line = line[:w]
			}
			fmt.Fprintln(tty, line)
		}
		bottom := path
		if offset+h-1 >= len(lines) {
			bottom = fmt.Sprintf("%s (END)", path)
		}
		fmt.Fprintf(tty, "\x1b[3m%s\x1b[0m", bottom)

		buf := make([]byte, 16)
		n, err := tty.Read(buf)
		if err != nil {
			break
		}
		if n == 0 {
			continue
		}
		b := buf[:n]
		if len(b) == 1 {
			switch b[0] {
			case 'q', 27:
				return
			case 'j', ' ':
				if offset+1 < len(lines) {
					offset++
				}
			case 'k':
				if offset > 0 {
					offset--
				}
			case 'g':
				offset = 0
			case 'G':
				if len(lines) > h-1 {
					offset = len(lines) - (h - 1)
				}
			}
		} else if b[0] == 27 && len(b) >= 3 && b[1] == '[' {
			switch b[2] {
			case 'A':
				if offset > 0 {
					offset--
				}
			case 'B':
				if offset+1 < len(lines) {
					offset++
				}
			}
		}
	}
}

func render(width, height int, st *state, statusBarExpr string) {
	var buf bytes.Buffer
	buf.WriteString("\x1b[2J\x1b[H")

	if st.showHelp {
		buf.WriteString(helpText)
		fmt.Fprint(os.Stderr, buf.String())
		return
	}

	if st.errorMsg != "" {
		buf.WriteString(st.currentPath + "\n")
		errMsg := st.errorMsg
		boxWidth := len(errMsg) + 4
		if boxWidth < 10 {
			boxWidth = 10
		}
		buf.WriteString("╭")
		buf.WriteString(strings.Repeat("─", boxWidth-2))
		buf.WriteString("╮\n")
		buf.WriteString("│ ")
		buf.WriteString(errMsg)
		buf.WriteString(" │\n")
		buf.WriteString("╰")
		buf.WriteString(strings.Repeat("─", boxWidth-2))
		buf.WriteString("╯\n")
		fmt.Fprint(os.Stderr, buf.String())
		return
	}

	if len(st.files) == 0 {
		buf.WriteString(st.currentPath + "\n")
		if st.preview {
			if st.withBorder {
				dirName := filepath.Base(st.currentPath)
				buf.WriteString(fmt.Sprintf("%-12s │\n", dirName))
				buf.WriteString("╭──────────╮ │ ╭─────────────────────────╮\n")
				buf.WriteString("│ No files │ │ │ Invalid file to preview │\n")
				buf.WriteString("╰──────────╯ │ ╰─────────────────────────╯\n")
			} else {
				buf.WriteString("╭──────────╮\n")
				buf.WriteString("│ No files │\n")
				buf.WriteString("╰──────────╯\n")
			}
		} else {
			buf.WriteString("╭──────────╮\n")
			buf.WriteString("│ No files │\n")
			buf.WriteString("╰──────────╯\n")
		}
		fmt.Fprint(os.Stderr, buf.String())
		return
	}

	if st.preview {
		selectedName := ""
		if st.cursor >= 0 && st.cursor < len(st.files) {
			selectedName = st.files[st.cursor].Name
		}
		base := filepath.Base(st.currentPath)
		if base == "." || base == "/" {
			base = st.currentPath
		}
		header := base
		if selectedName != "" {
			header = fmt.Sprintf("%s  %s", base, selectedName)
		}
		if st.withBorder {
			header = fmt.Sprintf("%s │ %s", base, selectedName)
		}
		buf.WriteString(header + "\n")

		var previewLines []string
		if st.cursor >= 0 && st.cursor < len(st.files) {
			sel := st.files[st.cursor]
			isDir := sel.Entry.IsDir()
			if !isDir {
				fi, err := os.Stat(sel.Path)
				if err == nil && fi.IsDir() {
					isDir = true
				}
			}
			if isDir {
				entries, _ := os.ReadDir(sel.Path)
				for _, e := range entries {
					name := e.Name()
					if st.hideHidden && strings.HasPrefix(name, ".") {
						continue
					}
					if st.dirOnly {
						if !e.IsDir() {
							continue
						}
					}
					previewLines = append(previewLines, name)
				}
				if len(previewLines) == 0 {
					previewLines = []string{"╭──────────╮", "│ No files │", "╰──────────╯"}
				}
			} else {
				data, err := os.ReadFile(sel.Path)
				if err != nil {
					previewLines = []string{fmt.Sprintf("Error: %v", err)}
				} else {
					if bytes.Contains(data, []byte{0}) {
						previewLines = []string{"binary"}
					} else {
						content := string(data)
						lines := strings.Split(content, "\n")
						previewLines = lines
					}
				}
			}
		}

		leftWidth := 20
		maxLen := 0
		for _, f := range st.files {
			l := len(f.Name)
			if st.showIcons {
				l += 2
			}
			if l > maxLen {
				maxLen = l
			}
		}
		if maxLen > 30 {
			maxLen = 30
		}
		leftWidth = maxLen + 2
		if leftWidth < 15 {
			leftWidth = 15
		}

		rowsAvailable := height - 2
		if rowsAvailable < 1 {
			rowsAvailable = 1
		}
		start := 0
		if st.cursor >= rowsAvailable {
			start = st.cursor - rowsAvailable + 1
		}
		for i := 0; i < rowsAvailable; i++ {
			fileIdx := start + i
			var leftPart string
			if fileIdx >= 0 && fileIdx < len(st.files) {
				f := st.files[fileIdx]
				name := f.Name
				if f.Entry.IsDir() {
					name = name + "/"
				}
				iconStr := ""
				if st.showIcons {
					iconStr = getIcon(f) + " "
				}
				leftPart = iconStr + name
				if fileIdx == st.cursor {
					leftPart = "\x1b[7m" + leftPart + "\x1b[0m"
				}
			}
			plainLeft := stripAnsi(leftPart)
			paddedLeft := leftPart
			if len(plainLeft) < leftWidth {
				paddedLeft = leftPart + strings.Repeat(" ", leftWidth-len(plainLeft))
			}
			var rightPart string
			if i < len(previewLines) {
				rightPart = previewLines[i]
			}
			if st.withBorder {
				buf.WriteString(paddedLeft + " │ " + rightPart + "\n")
			} else {
				buf.WriteString(paddedLeft + "  " + rightPart + "\n")
			}
		}
		if statusBarExpr != "" {
			var currentFile *fileEntry
			if st.cursor >= 0 && st.cursor < len(st.files) {
				currentFile = &st.files[st.cursor]
			}
			sb := evalStatusBar(statusBarExpr, currentFile, st.files)
			buf.WriteString(sb + "\n")
		} else if st.copiedMsg != "" {
			if time.Since(st.copiedTime) < 2*time.Second {
				buf.WriteString(fmt.Sprintf("copied: %s\n", st.copiedMsg))
			}
		}

	} else {
		if st.fuzzy {
			buf.WriteString(fmt.Sprintf("%s/%s\n", st.currentPath, st.fuzzyQuery))
		} else {
			buf.WriteString(st.currentPath + "\n")
		}
		maxLen := 0
		for _, f := range st.files {
			l := len(f.Name)
			if f.Entry.IsDir() {
				l++
			}
			if st.showIcons {
				l += 2
			}
			if l > maxLen {
				maxLen = l
			}
		}
		if maxLen == 0 {
			maxLen = 10
		}
		colWidth := maxLen + 4
		if colWidth < 15 {
			colWidth = 15
		}
		cols := width / colWidth
		if cols < 1 {
			cols = 1
		}
		rows := (len(st.files) + cols - 1) / cols

		for r := 0; r < rows; r++ {
			if r >= height-2 {
				break
			}
			for c := 0; c < cols; c++ {
				idx := c*rows + r
				if idx >= len(st.files) {
					continue
				}
				f := st.files[idx]
				name := f.Name
				if f.Entry.IsDir() {
					name = name + "/"
				}
				iconStr := ""
				if st.showIcons {
					iconStr = getIcon(f) + " "
				}
				display := iconStr + name
				if idx == st.cursor {
					display = "\x1b[7m" + display + "\x1b[0m"
				}
				plain := stripAnsi(display)
				if len(plain) < colWidth {
					display = display + strings.Repeat(" ", colWidth-len(plain))
				}
				buf.WriteString(display)
			}
			buf.WriteString("\n")
		}
		if statusBarExpr != "" {
			var currentFile *fileEntry
			if st.cursor >= 0 && st.cursor < len(st.files) {
				currentFile = &st.files[st.cursor]
			}
			sb := evalStatusBar(statusBarExpr, currentFile, st.files)
			buf.WriteString(sb + "\n")
		} else if st.copiedMsg != "" && time.Since(st.copiedTime) < 2*time.Second {
			buf.WriteString(fmt.Sprintf("copied: %s\n", st.copiedMsg))
		}
	}
	fmt.Fprint(os.Stderr, buf.String())
}

func stripAnsi(s string) string {
	var out strings.Builder
	inEsc := false
	for i := 0; i < len(s); {
		if !inEsc && s[i] == 0x1b {
			inEsc = true
			i++
			continue
		}
		if inEsc {
			if (s[i] >= 'A' && s[i] <= 'Z') || (s[i] >= 'a' && s[i] <= 'z') {
				inEsc = false
			}
			i++
			continue
		}
		out.WriteByte(s[i])
		i++
	}
	return out.String()
}
